import { Pipe, PipeTransform } from '@angular/core';

@Pipe({
  name: 'truncate'
})
export class TruncatePipe implements PipeTransform {

  transform(value: string, trancateLength: number, trail: string = '...'): string {
    if (!value) return '';
    return value.length > trancateLength ? value.substring(0, trancateLength) + trail : value;
  }
}
